/// Circuit state for one processing channel (nodal solver).
///
/// Contains per-sample state and sample-rate-dependent matrices.
/// Call [`set_sample_rate`](CircuitState::set_sample_rate) before processing
/// if the host sample rate differs from [`SAMPLE_RATE`].
/// Cold state: matrices only accessed on pot/switch/sample-rate changes.
/// Heap-allocated to keep the per-sample hot path in L2 cache.
#[derive(Clone, Debug)]
pub struct CircuitStateCold {
    pub s: [[f64; N]; N],
    pub k: [[f64; M]; M],
    pub s_ni: [[f64; M]; N],
    pub s_be: [[f64; N]; N],
    pub k_be: [[f64; M]; M],
    pub s_ni_be: [[f64; M]; N],
    pub s_sub: [[f64; N]; N],
    pub a_neg_sub: [[f64; N]; N],
    pub k_sub: [[f64; M]; M],
    pub s_ni_sub: [[f64; M]; N],
}

#[derive(Clone, Debug)]
pub struct CircuitState {
    /// Previous node voltages v[n-1]
    pub v_prev: [f64; N],

    /// Previous nonlinear currents i_nl[n-1]
    pub i_nl_prev: [f64; M],

    /// Nonlinear currents from two samples ago i_nl[n-2] (for NR predictor)
    pub i_nl_prev_prev: [f64; M],

    /// DC operating point (for reset/sleep/wake)
    pub dc_operating_point: [f64; N],

    /// Previous input sample for trapezoidal integration
    pub input_prev: f64,

    /// NR convergence diagnostic from the last sample's solve.
    ///
    /// Semantics:
    /// - 0..MAX_ITER-1: 0-indexed iteration at which convergence was detected
    ///   (i.e. `last_nr_iterations + 1` iterations actually ran)
    /// - MAX_ITER: loop exhausted without convergence → NR failed
    ///
    /// The check `last_nr_iterations >= MAX_ITER` is the BE-fallback trigger;
    /// storing `iter` (not `iter + 1`) is intentional so that convergence at
    /// the final permitted iteration (iter == MAX_ITER - 1) does not false-trigger.
    pub last_nr_iterations: u32,

    /// DC blocking filter: previous input samples (one per output)
    pub dc_block_x_prev: [f64; NUM_OUTPUTS],
    /// DC blocking filter: previous output samples (one per output)
    pub dc_block_y_prev: [f64; NUM_OUTPUTS],
    /// DC blocking filter coefficient (recomputed on sample rate change)
    pub dc_block_r: f64,

    /// Diagnostic: peak absolute output (pre-clamp)
    pub diag_peak_output: f64,
    /// Diagnostic: number of times output exceeded the ±output_clamp_v ceiling
    pub diag_clamp_count: u64,
    /// Diagnostic: number of times NR hit max iterations
    pub diag_nr_max_iter_count: u64,
    /// Diagnostic: device-samples where a pentode's grid conducts (Vgk > 0)
    /// or a BJT's base-collector junction is forward biased (saturation) —
    /// the regions the grid-off / forward-active reductions assume are never
    /// entered. Counted on the full models too (characterization, not a guard).
    pub diag_region_exit_count: u64,
    /// Diagnostic: number of backward Euler fallback activations
    pub diag_be_fallback_count: u64,
    /// Diagnostic: number of times the runtime BE-latch engaged (rising
    /// edges). Nonzero means the solver detected a self-sustaining Nyquist
    /// limit cycle on this stream and permanently switched that instance to
    /// the L-stable backward-Euler path (cleared by reset()). A plugin can
    /// surface this as "solver degraded". Always 0 on backward-Euler and
    /// force-trap builds.
    pub diag_be_latch_count: u64,
    /// Diagnostic: number of samples where the active-set rail resolve
    /// pinned at least one op-amp output (ActiveSet/ActiveSetBe only)
    pub diag_active_set_pin_count: u64,
    /// Diagnostic: number of times NaN triggered state reset
    pub diag_nan_reset_count: u64,
    /// Diagnostic: number of times a finite-but-implausible iterate
    /// (state magnitude beyond any physically-realizable circuit value)
    /// triggered state reset. NaN/Inf is caught by diag_nan_reset_count;
    /// this counts the "diverged but still is_finite()" gap.
    pub diag_magnitude_reset_count: u64,
    /// Diagnostic: number of samples that needed adaptive sub-stepping
    pub diag_substep_count: u64,
    /// Diagnostic: number of LU refactorizations performed
    pub diag_refactor_count: u64,
    /// Diagnostic: number of NR iterations whose Armijo line search was
    /// searched and failed (no `s` down to the 2^-10 floor met the
    /// sufficient-decrease test on a finite r0 > 1e-9). On such an
    /// iteration the loop takes the un-line-searched pnjlim/damp-limited
    /// step and continues; the always-checked residual gate still decides
    /// convergence. This is an expected event on stiff high-gain circuits,
    /// not an error — it is surfaced (not silenced) so the fall-through is
    /// observable. A non-finite or <=1e-9 r0 skips the search entirely and
    /// does NOT count here (ls_ok stays true).
    pub diag_ls_fail_count: u64,
    /// Diagnostic: number of samples hit by the global voltage-damping
    /// safety net. This is a legacy safeguard that scales v_new toward
    /// v_prev when any node moves more than ~2V (or 5% of max DC OP) in
    /// one sample. Per CLAUDE.md, output limiting must never mask solver
    /// bugs — treat a nonzero count here as a signal that the solver needs
    /// investigation, not as an acceptable steady-state.
    pub diag_voltage_damp_count: u64,

    // --- Cross-timestep chord method state (persisted LU factors) ---
    /// LU-factored Jacobian from previous convergence (chord method)
    pub chord_lu: [[f64; N]; N],
    /// Row equilibration scaling from LU factorization
    pub chord_dr: [f64; N],
    /// Column equilibration scaling from LU factorization
    pub chord_dc: [f64; N],
    /// Row permutation from LU factorization
    pub chord_perm: [usize; N],
    /// Device Jacobian consistent with chord_lu (for companion RHS)
    pub chord_j_dev: [f64; M * M],
    /// Whether chord LU factors are valid (false until first convergence)
    pub chord_valid: bool,
    /// Whether chord_lu holds DENSE (partial-pivoting) factors from the
    /// runtime fallback (sparse static pivoting rejected: tiny pivot or
    /// excessive element growth). Selects the matching back-solve.
    pub chord_dense: bool,

    /// A matrix: G + alpha*C (trapezoidal), recomputed by set_sample_rate
    pub a: [[f64; N]; N],
    /// A_neg matrix: alpha*C - G (trapezoidal history), recomputed by set_sample_rate
    pub a_neg: [[f64; N]; N],
    /// A_be matrix: G + (1/T)*C (backward Euler), recomputed by set_sample_rate
    pub a_be: [[f64; N]; N],
    /// A_neg_be matrix: (1/T)*C (backward Euler history), recomputed by set_sample_rate
    pub a_neg_be: [[f64; N]; N],
    /// Cold state: Schur complement + work matrices (heap-allocated,
    /// only accessed on pot/switch changes and sample rate changes).
    pub cold: Box<CircuitStateCold>,

    /// Current HOST sample rate (Hz), as passed to `set_sample_rate`.
    /// Multiply by `OVERSAMPLING_FACTOR` to get the internal rate at
    /// consumption sites (rebuild_matrices, op-amp slew dt, substep
    /// alpha). Matches the DK path's field semantics (API parity).
    pub current_sample_rate: f64,

    // --- Runtime-adjustable device parameters ---
    /// Device 0 IS (Bjt) — runtime adjustable
    pub device_0_is: f64,
    /// Device 0 VT (Bjt) — runtime adjustable
    pub device_0_vt: f64,
    /// Device 0 BETA_F (Bjt) — runtime adjustable
    pub device_0_bf: f64,
    /// Device 0 BETA_R (Bjt) — runtime adjustable
    pub device_0_br: f64,
    /// Device 1 IS (Bjt) — runtime adjustable
    pub device_1_is: f64,
    /// Device 1 VT (Bjt) — runtime adjustable
    pub device_1_vt: f64,
    /// Device 1 BETA_F (Bjt) — runtime adjustable
    pub device_1_bf: f64,
    /// Device 1 BETA_R (Bjt) — runtime adjustable
    pub device_1_br: f64,
    /// Device 2 IS (Bjt) — runtime adjustable
    pub device_2_is: f64,
    /// Device 2 VT (Bjt) — runtime adjustable
    pub device_2_vt: f64,
    /// Device 2 BETA_F (Bjt) — runtime adjustable
    pub device_2_bf: f64,
    /// Device 2 BETA_R (Bjt) — runtime adjustable
    pub device_2_br: f64,
    /// Device 3 IS (Bjt) — runtime adjustable
    pub device_3_is: f64,
    /// Device 3 VT (Bjt) — runtime adjustable
    pub device_3_vt: f64,
    /// Device 3 BETA_F (Bjt) — runtime adjustable
    pub device_3_bf: f64,
    /// Device 3 BETA_R (Bjt) — runtime adjustable
    pub device_3_br: f64,
    /// Device 4 IS (Bjt) — runtime adjustable
    pub device_4_is: f64,
    /// Device 4 VT (Bjt) — runtime adjustable
    pub device_4_vt: f64,
    /// Device 4 BETA_F (Bjt) — runtime adjustable
    pub device_4_bf: f64,
    /// Device 4 BETA_R (Bjt) — runtime adjustable
    pub device_4_br: f64,
    /// Device 5 IS (Bjt) — runtime adjustable
    pub device_5_is: f64,
    /// Device 5 VT (Bjt) — runtime adjustable
    pub device_5_vt: f64,
    /// Device 5 BETA_F (Bjt) — runtime adjustable
    pub device_5_bf: f64,
    /// Device 5 BETA_R (Bjt) — runtime adjustable
    pub device_5_br: f64,
    /// Device 6 IS (Bjt) — runtime adjustable
    pub device_6_is: f64,
    /// Device 6 VT (Bjt) — runtime adjustable
    pub device_6_vt: f64,
    /// Device 6 BETA_F (Bjt) — runtime adjustable
    pub device_6_bf: f64,
    /// Device 6 BETA_R (Bjt) — runtime adjustable
    pub device_6_br: f64,
    /// Runtime value for voltage source V1 (RHS row 20).
    pub v_rail_pos_offset: f64,
    /// Runtime value for voltage source V2 (RHS row 21).
    pub v_rail_neg_offset: f64,
}

impl Default for CircuitState {
    fn default() -> Self {
        let mut state = Self {
            v_prev: DC_OP,
            i_nl_prev: DC_NL_I,
            i_nl_prev_prev: DC_NL_I,
            dc_operating_point: DC_OP,
            input_prev: 0.0,
            last_nr_iterations: 0,
            dc_block_x_prev: [5.77393715525042085e-3],
            dc_block_y_prev: [0.0],
            dc_block_r: DC_BLOCK_R,
            diag_peak_output: 0.0,
            diag_clamp_count: 0,
            diag_nr_max_iter_count: 0,
            diag_region_exit_count: 0,
            diag_be_fallback_count: 0,
            diag_be_latch_count: 0,
            diag_active_set_pin_count: 0,
            diag_nan_reset_count: 0,
            diag_magnitude_reset_count: 0,
            diag_substep_count: 0,
            diag_refactor_count: 0,
            diag_ls_fail_count: 0,
            diag_voltage_damp_count: 0,
            chord_lu: [[0.0; N]; N],
            chord_dr: [1.0; N],
            chord_dc: [1.0; N],
            chord_perm: {
                {
                    let mut p = [0usize; N];
                    let mut i = 0;
                    while i < N {
                        p[i] = i;
                        i += 1;
                    }
                    p
                }
            },
            chord_j_dev: [0.0; M * M],
            chord_valid: false,
            chord_dense: false,
            a: A_DEFAULT,
            a_neg: A_NEG_DEFAULT,
            a_be: A_BE_DEFAULT,
            a_neg_be: A_NEG_BE_DEFAULT,
            cold: Box::new(CircuitStateCold {
                s: S_DEFAULT,
                k: K_DEFAULT,
                s_ni: S_NI_DEFAULT,
                s_be: S_BE_DEFAULT,
                k_be: K_BE_DEFAULT,
                s_ni_be: S_NI_BE_DEFAULT,
                s_sub: S_SUB_DEFAULT,
                a_neg_sub: A_NEG_SUB_DEFAULT,
                k_sub: K_SUB_DEFAULT,
                s_ni_sub: S_NI_SUB_DEFAULT,
            }),
            current_sample_rate: 8.82000000000000000e4,
            device_0_is: DEVICE_0_IS,
            device_0_vt: DEVICE_0_VT,
            device_0_bf: DEVICE_0_BETA_F,
            device_0_br: DEVICE_0_BETA_R,
            device_1_is: DEVICE_1_IS,
            device_1_vt: DEVICE_1_VT,
            device_1_bf: DEVICE_1_BETA_F,
            device_1_br: DEVICE_1_BETA_R,
            device_2_is: DEVICE_2_IS,
            device_2_vt: DEVICE_2_VT,
            device_2_bf: DEVICE_2_BETA_F,
            device_2_br: DEVICE_2_BETA_R,
            device_3_is: DEVICE_3_IS,
            device_3_vt: DEVICE_3_VT,
            device_3_bf: DEVICE_3_BETA_F,
            device_3_br: DEVICE_3_BETA_R,
            device_4_is: DEVICE_4_IS,
            device_4_vt: DEVICE_4_VT,
            device_4_bf: DEVICE_4_BETA_F,
            device_4_br: DEVICE_4_BETA_R,
            device_5_is: DEVICE_5_IS,
            device_5_vt: DEVICE_5_VT,
            device_5_bf: DEVICE_5_BETA_F,
            device_5_br: DEVICE_5_BETA_R,
            device_6_is: DEVICE_6_IS,
            device_6_vt: DEVICE_6_VT,
            device_6_bf: DEVICE_6_BETA_F,
            device_6_br: DEVICE_6_BETA_R,
            v_rail_pos_offset: 0.0,
            v_rail_neg_offset: 0.0,
        };
        state.warmup();
        state
    }
}

impl CircuitState {
    /// Reset to DC operating point
    pub fn reset(&mut self) {
        self.v_prev = self.dc_operating_point;
        self.i_nl_prev = DC_NL_I;
        self.i_nl_prev_prev = DC_NL_I;
        self.input_prev = 0.0;
        self.last_nr_iterations = 0;
        self.chord_valid = false;
        self.dc_block_x_prev[0] = self.dc_operating_point[8];
        self.dc_block_y_prev = [0.0; NUM_OUTPUTS];
        self.diag_peak_output = 0.0;
        self.diag_clamp_count = 0;
        self.diag_nr_max_iter_count = 0;
        self.diag_region_exit_count = 0;
        self.diag_be_fallback_count = 0;
        self.diag_be_latch_count = 0;
        self.diag_active_set_pin_count = 0;
        self.diag_nan_reset_count = 0;
        self.diag_magnitude_reset_count = 0;
        self.diag_voltage_damp_count = 0;
        self.diag_substep_count = 0;
        self.diag_refactor_count = 0;
        self.diag_ls_fail_count = 0;
        self.device_0_is = DEVICE_0_IS;
        self.device_0_vt = DEVICE_0_VT;
        self.device_0_bf = DEVICE_0_BETA_F;
        self.device_0_br = DEVICE_0_BETA_R;
        self.device_1_is = DEVICE_1_IS;
        self.device_1_vt = DEVICE_1_VT;
        self.device_1_bf = DEVICE_1_BETA_F;
        self.device_1_br = DEVICE_1_BETA_R;
        self.device_2_is = DEVICE_2_IS;
        self.device_2_vt = DEVICE_2_VT;
        self.device_2_bf = DEVICE_2_BETA_F;
        self.device_2_br = DEVICE_2_BETA_R;
        self.device_3_is = DEVICE_3_IS;
        self.device_3_vt = DEVICE_3_VT;
        self.device_3_bf = DEVICE_3_BETA_F;
        self.device_3_br = DEVICE_3_BETA_R;
        self.device_4_is = DEVICE_4_IS;
        self.device_4_vt = DEVICE_4_VT;
        self.device_4_bf = DEVICE_4_BETA_F;
        self.device_4_br = DEVICE_4_BETA_R;
        self.device_5_is = DEVICE_5_IS;
        self.device_5_vt = DEVICE_5_VT;
        self.device_5_bf = DEVICE_5_BETA_F;
        self.device_5_br = DEVICE_5_BETA_R;
        self.device_6_is = DEVICE_6_IS;
        self.device_6_vt = DEVICE_6_VT;
        self.device_6_bf = DEVICE_6_BETA_F;
        self.device_6_br = DEVICE_6_BETA_R;
        self.v_rail_pos_offset = 0.0;
        self.v_rail_neg_offset = 0.0;
        if (self.current_sample_rate - SAMPLE_RATE).abs() < 0.5 {
            self.a = A_DEFAULT;
            self.a_neg = A_NEG_DEFAULT;
            self.a_be = A_BE_DEFAULT;
            self.a_neg_be = A_NEG_BE_DEFAULT;
            self.cold.s = S_DEFAULT;
            self.cold.k = K_DEFAULT;
            self.cold.s_ni = S_NI_DEFAULT;
            self.cold.s_be = S_BE_DEFAULT;
            self.cold.k_be = K_BE_DEFAULT;
            self.cold.s_ni_be = S_NI_BE_DEFAULT;
            self.cold.s_sub = S_SUB_DEFAULT;
            self.cold.a_neg_sub = A_NEG_SUB_DEFAULT;
            self.cold.k_sub = K_SUB_DEFAULT;
            self.cold.s_ni_sub = S_NI_SUB_DEFAULT;
        } else {
            self.rebuild_matrices(self.current_sample_rate * 1.0);
        }
        self.warmup();
    }

    /// Run silent warmup samples to settle into the correct operating point.
    ///
    /// Call after construction or reset() to ensure the circuit settles into
    /// the physically correct basin of attraction. Without warmup, circuits
    /// with high-gain op-amps may lock into a parasitic equilibrium.
    ///
    /// The default `CircuitState::default()` calls this automatically.
    pub fn warmup(&mut self) {
        for _ in 0..50 {
            process_sample(0.0, self);
        }
    }

    /// Set DC operating point (call after DC analysis)
    pub fn set_dc_operating_point(&mut self, v_dc: [f64; N]) {
        self.dc_operating_point = v_dc;
        self.v_prev = v_dc;
    }

    /// Read the baked DC operating point for this circuit.
    ///
    /// Solution to the nonlinear DC system computed at codegen time (at nominal
    /// pot/switch values) and frozen into `DC_OP`. Prefer this over `v_prev` when
    /// you want the *designed* bias point — `v_prev` carries per-sample dynamics.
    #[inline]
    pub fn dc_op(&self) -> &[f64; N] {
        &self.dc_operating_point
    }

    /// Pretty-print the DC operating point with user-assigned node names.
    ///
    /// Writes one line per named node to `stderr`. Intended for plugin
    /// bring-up diagnostics, not the audio thread (formatting allocates).
    pub fn dc_op_dump(&self) {
        let dc = &self.dc_operating_point;
        eprintln!("  V(IN) = {:+.4} V", dc[0]);
        eprintln!("  V(IN_AC) = {:+.4} V", dc[1]);
        eprintln!("  V(EMIT_PAIR) = {:+.4} V", dc[2]);
        eprintln!("  V(VREG15) = {:+.4} V", dc[3]);
        eprintln!("  V(COLL7) = {:+.4} V", dc[4]);
        eprintln!("  V(COLL8) = {:+.4} V", dc[5]);
        eprintln!("  V(FB_INV) = {:+.4} V", dc[6]);
        eprintln!("  V(VN) = {:+.4} V", dc[7]);
        eprintln!("  V(OUT) = {:+.4} V", dc[8]);
        eprintln!("  V(C10_NODE) = {:+.4} V", dc[9]);
        eprintln!("  V(DRV_BOT) = {:+.4} V", dc[10]);
        eprintln!("  V(VP) = {:+.4} V", dc[11]);
        eprintln!("  V(BOOT) = {:+.4} V", dc[12]);
        eprintln!("  V(VAS_OUT) = {:+.4} V", dc[13]);
        eprintln!("  V(BIAS_MID) = {:+.4} V", dc[14]);
        eprintln!("  V(BASE11) = {:+.4} V", dc[15]);
        eprintln!("  V(NODEC) = {:+.4} V", dc[16]);
        eprintln!("  V(BASE13) = {:+.4} V", dc[17]);
        eprintln!("  V(NODED) = {:+.4} V", dc[18]);
        eprintln!("  V(ZOB) = {:+.4} V", dc[19]);
    }

    /// Recompute all sample-rate-dependent matrices for a new sample rate.
    ///
    /// Call this once during plugin initialization (NOT on the audio thread).
    /// Rebuilds A, A_neg, A_be, A_neg_be from stored G and C matrices.
    pub fn set_sample_rate(&mut self, sample_rate: f64) {
        if !(sample_rate > 0.0 && sample_rate.is_finite()) {
            return;
        }

        self.current_sample_rate = sample_rate;

        // If same as codegen sample rate, reset to defaults
        if (sample_rate - SAMPLE_RATE).abs() < 0.5 {
            self.a = A_DEFAULT;
            self.a_neg = A_NEG_DEFAULT;
            self.a_be = A_BE_DEFAULT;
            self.a_neg_be = A_NEG_BE_DEFAULT;
            self.cold.s = S_DEFAULT;
            self.cold.s_be = S_BE_DEFAULT;
            self.cold.k = K_DEFAULT;
            self.cold.s_ni = S_NI_DEFAULT;
            self.cold.k_be = K_BE_DEFAULT;
            self.cold.s_ni_be = S_NI_BE_DEFAULT;
            self.cold.s_sub = S_SUB_DEFAULT;
            self.cold.a_neg_sub = A_NEG_SUB_DEFAULT;
            self.cold.k_sub = K_SUB_DEFAULT;
            self.cold.s_ni_sub = S_NI_SUB_DEFAULT;
            self.dc_block_r = DC_BLOCK_R;
            // POLICY: transient state — oversampler filter history,
            // DC-blocker history, solver v_prev/i_nl history — is
            // PRESERVED here. Only coefficients and matrices are
            // restored: a same-rate call is a no-op reconfiguration
            // and must not click (DK-template parity).
            return;
        }

        let internal_rate = sample_rate * 1.0;
        self.rebuild_matrices(internal_rate);

        // Recompute DC blocking coefficient
        self.dc_block_r = 1.0 - 2.0 * std::f64::consts::PI * 5.0 / internal_rate;
        self.dc_block_x_prev[0] = self.dc_operating_point[8];
        self.dc_block_y_prev = [0.0; NUM_OUTPUTS];
    }

    /// Recompute A, A_neg, A_be, A_neg_be from G and C.
    ///
    /// Called by set_sample_rate, set_pot, and set_switch.
    /// The Schur matrices (S/K/S_NI) are not rebuilt: the full-LU path
    /// never reads them.
    pub fn rebuild_matrices(&mut self, internal_rate: f64) {
        let alpha = internal_rate; // backward Euler: alpha = 1/T
        let alpha_be = internal_rate;
        let alpha_sub = 4.0 * internal_rate; // trap at 2× rate

        for i in 0..N {
            for j in 0..N {
                self.a[i][j] = G[i][j] + alpha * C[i][j];
                self.a_neg[i][j] = alpha * C[i][j];
                self.a_be[i][j] = G[i][j] + alpha_be * C[i][j];
                self.a_neg_be[i][j] = alpha_be * C[i][j];
            }
        }
        for i in 0..N {
            for j in 0..N {
                self.cold.a_neg_sub[i][j] = alpha_sub * C[i][j] - G[i][j];
            }
        }
        for i in 20..23 {
            for j in 0..N {
                self.a_neg[i][j] = 0.0;
                self.a_neg_be[i][j] = 0.0;
            }
        }
        for i in 20..23 {
            for j in 0..N {
                self.cold.a_neg_sub[i][j] = 0.0;
            }
        }

        // Invalidate chord LU cache (matrices changed)
        self.chord_valid = false;
    }
}

