                    // Armijo backtracking line search on ||F|| along the limited Newton ray.
                    let mut ls_ok = true;
                    {
                        // r0 = ||F(v_sub)||: reuses the device currents `i_nl` the NR body
                        // already evaluated at this exact v_sub (bit-identical to a fresh
                        // kcl_residual — same N_v·v, same device fn, no pnjlim on the eval).
                        let (r0, _) = kcl_residual_inl(&v_sub, &rhs_s, &a_sub, &i_nl);
                        if r0.is_finite() && r0 > 1e-9 {
                            let mut s = 1.0_f64;
                            let mut accepted = false;
                            while s >= (1.0 / 1024.0) {
                                let mut vc = v_sub;
                                for i in 0..N {
                                    vc[i] += (alpha * s) * (v_new_s[i] - v_sub[i]);
                                }
                                let (rc, _) = kcl_residual(&vc, &rhs_s, &a_sub, state);
                                if rc <= (1.0 - 1e-4 * s) * r0 {
                                    accepted = true;
                                    break;
                                }
                                s *= 0.5;
                            }
                            if accepted {
                                alpha *= s;
                            } else {
                                ls_ok = false;
                            }
                        }
                    }
                    if !ls_ok {
                        state.diag_ls_fail_count += 1;
                    }
                    let mut max_step = 0.0f64;
                    for i in 0..N_NODES {
                        let step = v_new_s[i] - v_sub[i];
                        if step.abs() > max_step {
                            max_step = step.abs();
                        }
                    }
                    for i in 0..N {
                        v_sub[i] += alpha * (v_new_s[i] - v_sub[i]);
                    }
